import json
import socket
import time

HOST = "127.0.0.1"
PORT = 2078
NAMES = ["Johnny Silverhand", "Hanako", "Song So Ri"]
FORMATIONS = ["rank", "file", "wedge"]


def send(line, timeout):
    sock = socket.create_connection((HOST, PORT), timeout=timeout)
    try:
        sock.settimeout(timeout)
        sock.sendall((line + "\n").encode())
        buf = b""
        while b"\n" not in buf:
            chunk = sock.recv(65536)
            if not chunk:
                break
            buf += chunk
    finally:
        sock.close()
    text = buf.decode().strip()
    return json.loads(text) if text else {"error": "empty"}


def place_ok(reply):
    if reply.get("type") != "place" or reply.get("error"):
        return False
    for actor in reply.get("actors") or []:
        if actor.get("error"):
            return False
    return True


def main():
    print("PRECLEAR", flush=True)
    pre = send('{"cmd":"clear"}', 30)
    print(json.dumps(pre), flush=True)
    if pre.get("type") != "clear" or pre.get("error"):
        raise SystemExit(1)
    time.sleep(2)
    for formation in FORMATIONS:
        for slot, name in enumerate(NAMES, 1):
            cmd = json.dumps(
                {
                    "cmd": "place",
                    "names": [name],
                    "formation": formation,
                    "slot": slot,
                    "slots": 3,
                }
            )
            print(f"PLACE {formation} {slot} {name}", flush=True)
            placed = send(cmd, 25)
            print(json.dumps(placed), flush=True)
            if not place_ok(placed):
                raise SystemExit(1)
            time.sleep(4)
            print(f"CLEAR {formation} {slot}", flush=True)
            cleared = send('{"cmd":"clear"}', 30)
            print(json.dumps(cleared), flush=True)
            if cleared.get("type") != "clear" or cleared.get("error"):
                raise SystemExit(1)
            time.sleep(2)
    print("DONE", flush=True)


if __name__ == "__main__":
    main()
